  def check_concrete_outputs(api_qualified_threat: Mining_Threat_Retreat_Supervisor.Qualified_Threat,
                             api_threat_invalidity: Mining_Threat_Retreat_Supervisor.Threat_Invalidity,
                             api_threat_publication: Mining_Threat_Retreat_Supervisor.Threat_Publication_Facts): Unit = {
    var failureReasons: ISZ[ST] = ISZ()

